uint8 constant FIELD_TOKEN_OUT = 5;
uint8 constant FIELD_ORIGIN_OPS = 6;
uint8 constant FIELD_DEST_OPS = 7;
uint8 constant FIELD_QUALIFICATION = 8;
uint8 constant FIELD_RECIPIENT_IS_SPONSOR = 9;

