//////////////////////////////////////////////////////////////*/

/// @notice Stored qualification configuration
/// @param useArbiterHash If true, use arbiter.qualificationHash() for hashing
/// @param rules Parameter validation rules
struct QualificationRulesStorage {
    bool useArbiterHash;
    ParamRules rules;
}

